Method.Implementation:
Set sc = $$$OK Set file = "" Set ts = "" Set inst = "" Set oldIO = $IO
Try { // Cleanup old logs Do ..CleanupOldFiles("/tmp","global_size_report_",..RetentionDays)
// Get instance name Set inst = ##class(%SYS.System).GetInstanceName() If inst="" Set inst="UNKNOWN"
// Build timestamp Set ts = $ZDATETIME($H,3) Set ts = $Replace(ts," ","_") Set ts = $Replace(ts,":","-") Set ts = $Replace(ts,"/","-")
// Build filename (WITH INSTANCE) Set file = "/tmp/global_size_report_"_inst_"_"_ts_".log"
Open file:"WNS":5 If '$TEST { Set sc = $$$ERROR($$$GeneralError,"Unable to open output file: "_file) Quit }
Use file Write "RUN START: ",$ZDATETIME($H,3),! Write "Instance: ",inst,! Write "Task Class: IHC.ITF.ITFCOMMON.Tasks.GlobalSizeAllNamespacesTask",!! Write "Calling Utils class...",!!
Do ##class(IHC.ITF.ITFCOMMON.Utils.GlobalSizeAllNamespaces).Run(..TopN,..FastFlag,..Debug)
Write !!,"RUN END: ",$ZDATETIME($H,3),!
Close file Use oldIO
} Catch ex { Set sc = ex.AsStatus() If file'="" { Use file Write !,"ERROR: ",ex.DisplayString(),! Close file } Use oldIO }
Quit sc

If pDays'>0 Quit
// deletes ANY file starting with global_size_report_*.log (all instances) Set cmd = "find "_pDir_" -maxdepth 1 -type f -name '"_pPrefix_"*.log' -mtime +"_(pDays-1)_" -delete >/dev/null 2>&1" Set rc = $ZF(-1,cmd)
Quit
